package app

import (
	"embed"
	"io/fs"
)

//go:embed static/*
var assets embed.FS
var staticFS, _ = fs.Sub(assets, "static")

const layout = `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{{.Title}} · CJM</title><link rel="stylesheet" href="/static/app.css"><meta name="htmx-config" content='{"includeIndicatorStyles":false,"allowEval":false,"allowScriptTags":false}'><script src="/static/htmx.min.js" defer></script><script src="/static/app.js" defer></script></head><body hx-history="false"><a class="skip" href="#main">Ir al contenido</a><header><a class="brand" href="/">CJM <span>Centro Judicial de Mediación</span></a>{{if .User}}<div class="identity">{{.User.Nombre}} · {{.User.Role}}<form method="post" action="/logout"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="secondary">Salir</button></form></div>{{end}}</header>{{if .User}}<nav aria-label="Navegación principal"><a href="/">Inicio</a><a href="/calendario">Calendario</a>{{if eq .User.Role "ADMIN"}}<a href="/admin/mediaciones">Mediaciones</a><a href="/admin/usuarios">Mediadores</a><a href="/admin/noticias">Noticias</a><a href="/admin/dnis">DNI habilitados</a><a href="/admin/exportaciones">Exportaciones</a><a href="/admin/bloqueos">Días bloqueados</a><a href="/admin/usuarios?role=ADMIN">Administradores</a><a href="/admin/auditoria">Auditoría</a>{{else}}<a href="/mis-mediaciones">Mis mediaciones</a>{{end}}</nav>{{end}}<main id="main"><h1>{{.Title}}</h1>{{if .Message}}<p class="notice" role="status">{{.Message}}</p>{{end}}{{template "content" .}}</main><footer>CJM · Córdoba · Horarios de Argentina</footer></body></html>{{define "content"}}`
const loginTemplate = `<section class="card narrow"><p>Ingrese con su DNI o usuario administrativo.</p><form action="/login" method="post"><input type="hidden" name="csrf" value="{{.CSRF}}"><label>DNI / usuario<input name="username" required autocomplete="username" maxlength="254"></label><label>Contraseña<input type="password" name="password" required autocomplete="current-password" maxlength="72"></label><button>Ingresar</button></form><p><a href="/registro">Registrar DNI habilitado</a></p><p class="muted">Si olvidó su contraseña, comuníquese con un funcionario.</p></section>`
const registerTemplate = `<section class="card narrow"><form action="/registro" method="get"><label>DNI<input name="dni" value="{{.DNI}}" required maxlength="12" inputmode="numeric"></label><button>Consultar DNI</button></form>{{if .Error}}<p class="notice" role="alert">{{.Error}}</p>{{end}}{{if .DNI}}<h2>{{.Nombre}} {{.Apellido}}</h2><p>{{.Email}}</p><form method="post" action="/registro" enctype="multipart/form-data"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="dni" value="{{.DNI}}"><label>Teléfono<input name="phone" type="tel" autocomplete="tel" required maxlength="60"></label><label>Contraseña (12 a 72 bytes)<input name="password" type="password" minlength="12" maxlength="72" required autocomplete="new-password"></label><label>Confirmar contraseña<input name="confirm" type="password" minlength="12" maxlength="72" required autocomplete="new-password"></label><label>Foto (JPEG o PNG, máximo 5 MB)<input type="file" name="photo" accept="image/jpeg,image/png" required></label><button>Completar registro</button></form>{{end}}</section>`
const newsCards = `<h2>Noticias recientes</h2><div class="cards">{{range .News}}<article class="card">{{if .Image}}<img class="news-image" src="/uploads/{{.Image}}" alt="" loading="lazy">{{end}}<p class="muted">{{dateES .Date}}</p><h3>{{.Title}}</h3><p class="prewrap">{{.Content}}</p></article>{{else}}<p>No hay noticias publicadas.</p>{{end}}</div>`
const homeTemplate = `<div class="toolbar"><a class="button" href="/calendario">Reservar una mediación</a><a href="/mis-mediaciones">Ver mis mediaciones</a></div><h2>Próximas mediaciones</h2><div class="cards">{{range .Mediations}}<article class="card"><strong>{{dateES .Date}} · {{.Start}}</strong><p>{{.Sede}} · {{.State}}</p><h3>{{.Title}}</h3><p>Expediente {{.Case}}</p><p>{{.Name1}} / {{.Name2}}</p></article>{{else}}<p>No tiene próximas mediaciones.</p>{{end}}</div>` + newsCards
const dashboardTemplate = `{{if .Pending}}<aside class="warning" role="alert">Hay mediaciones de {{.Pending}} día(s) pendientes de exportación. La más antigua es del {{dateES .Oldest}}. <a href="/admin/exportaciones">Exportar mediaciones</a>. No se eliminarán mientras estén pendientes.</aside>{{end}}<div class="stats"><article class="card"><span>Mediaciones hoy</span><strong>{{.Total}}</strong></article>{{range $key,$value:=.Counts}}<article class="card"><span>{{$key}}</span><strong>{{$value}}</strong></article>{{end}}</div><div class="toolbar"><a class="button" href="/admin/mediaciones">Abrir panel del día</a><a href="/admin/exportaciones">Exportar mediaciones</a></div>{{if .BlockDate}}<p class="notice">Próximo día bloqueado: {{dateES .BlockDate}} · {{.Reason}}</p>{{end}}` + newsCards
const calendarTemplate = `<section id="calendar"><form class="toolbar" action="/calendario" method="get" hx-get="/calendario" hx-target="#calendar" hx-select="#calendar" hx-swap="outerHTML" hx-push-url="true"><label>Sede<select name="sede">{{range .Sedes}}<option value="{{.Code}}" {{if eq $.Sede .Code}}selected{{end}}>{{.Name}}</option>{{end}}</select></label><input type="hidden" name="semana" value="{{(index .Days 0).Date}}"><button>Ver calendario</button></form><div class="toolbar">{{if .HasPrev}}<a class="button secondary" href="/calendario?sede={{.Sede}}&semana={{.Prev}}" hx-get="/calendario?sede={{.Sede}}&semana={{.Prev}}" hx-target="#calendar" hx-select="#calendar" hx-swap="outerHTML" hx-push-url="true">← Anterior</a>{{end}}<strong>Semana del {{.Week}}</strong>{{if .HasNext}}<a class="button secondary" href="/calendario?sede={{.Sede}}&semana={{.Next}}" hx-get="/calendario?sede={{.Sede}}&semana={{.Next}}" hx-target="#calendar" hx-select="#calendar" hx-swap="outerHTML" hx-push-url="true">Siguiente →</a>{{end}}</div><p class="muted">{{.Name}} · Reservas hasta el {{.Limit}} · Lunes a viernes</p><div class="calendar">{{range .Days}}<section class="day"><h2>{{.Label}}</h2>{{range .Slots}}{{if and .Available (eq $.User.Role "MEDIADOR")}}<a class="slot available" href="/reservar?sede={{.Sede}}&fecha={{.Date}}&hora={{.Start}}"><strong>{{.Start}}</strong><span>{{.Label}}</span></a>{{else}}<div class="slot {{if .Available}}available{{else}}unavailable{{end}}"><strong>{{.Start}}</strong><span>{{.Label}}</span></div>{{end}}{{end}}</section>{{end}}</div></section>`
const reserveTemplate = `<section class="card narrow"><p>Usted será el mediador 1. Ambos participantes verán la reserva.</p><form method="post" action="/reservar"><input type="hidden" name="csrf" value="{{.CSRF}}"><label>Sede<select name="sede">{{range .Sedes}}<option value="{{.Code}}" {{if eq $.Sede .Code}}selected{{end}}>{{.Name}}</option>{{end}}</select></label><label>Fecha<input type="text" inputmode="numeric" placeholder="dd/mm/aaaa" pattern="[0-9]{2}/[0-9]{2}/[0-9]{4}" maxlength="10" name="date" value="{{dateES .Date}}" required></label><label>Hora<input type="time" name="start" value="{{.Start}}" required></label><label>Buscar mediador 2<input type="search" name="q" autocomplete="off" placeholder="Nombre, apellido o DNI" hx-get="/mediadores/buscar" hx-trigger="input changed delay:150ms, search" hx-target="#mediator-picker" hx-select="#mediator-picker" hx-swap="outerHTML" hx-sync="this:replace"></label>` + mediatorPickerTemplate + `<label>Carátula<input name="title" maxlength="300" required></label><label>Número de expediente<input name="case" maxlength="120" required></label><button>Confirmar reserva</button></form></section>`
const myTemplate = `<div class="cards">{{range .Mediations}}<article class="card"><h2>{{dateES .Date}} · {{.Start}}</h2><p>{{.Sede}} · <span class="badge">{{.State}}</span></p><h3>{{.Title}}</h3><p>Expediente {{.Case}}</p><p>{{.Name1}} / {{.Name2}}</p>{{if .Result}}<p>Resultado: {{.Result}}</p>{{end}}{{if index $.CanCancel .ID}}<form method="post" action="/cancelar" data-confirm="¿Cancelar esta reserva para ambos mediadores?"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="id" value="{{.ID}}"><button class="danger">Cancelar reserva</button></form>{{end}}</article>{{else}}<p>No tiene mediaciones en este período.</p>{{end}}</div>`
const adminMTemplate = `<div class="toolbar"><a class="button secondary" href="/admin/mediaciones?date={{.Yesterday}}">Ayer</a><a class="button" href="/admin/mediaciones">Hoy</a><a class="button secondary" href="/admin/mediaciones?date={{.Tomorrow}}">Mañana</a></div><section id="daily">{{if and .Past .Pending}}<p class="warning" role="alert">Recordá exportar las mediaciones del {{dateES .Date}}. Se eliminarán una vez exportadas y vencido el período operativo. <a href="/admin/exportaciones">Exportar</a></p>{{end}}<form class="toolbar" method="get" action="/admin/mediaciones" hx-get="/admin/mediaciones" hx-target="#daily" hx-select="#daily" hx-swap="outerHTML" hx-push-url="true"><label>Fecha<input type="text" inputmode="numeric" placeholder="dd/mm/aaaa" pattern="[0-9]{2}/[0-9]{2}/[0-9]{4}" maxlength="10" name="date" value="{{dateES .Date}}" required></label><label>Estado<select name="state"><option value="">Todos</option>{{range $s:=states}}<option {{if eq $.State $s}}selected{{end}}>{{$s}}</option>{{end}}</select></label><label>Resultado<select name="result"><option value="">Todos</option>{{range $s:=results}}<option {{if eq $.Result $s}}selected{{end}}>{{$s}}</option>{{end}}</select></label><button>Filtrar</button></form><div class="table-wrap"><table><caption>Mediaciones del {{dateES .Date}}</caption><thead><tr><th>Hora / sede</th><th>Expediente / carátula</th><th>Mediadores</th><th>Estado / resultado</th><th>Acciones</th></tr></thead><tbody>{{range .Mediations}}<tr><td>{{.Start}}<br>{{.Sede}}</td><td>{{.Case}}<br>{{.Title}}</td><td>{{.Name1}}<br>{{.Name2}}</td><td>{{.State}}<br>{{.Result}}</td><td><a class="button secondary" href="/admin/editar?id={{.ID}}">Editar</a> <a class="button secondary" href="/admin/estado?id={{.ID}}">Estado</a></td></tr>{{else}}<tr><td colspan="5">No hay mediaciones para estos filtros.</td></tr>{{end}}</tbody></table></div><div class="toolbar">{{if gt .Page 1}}<a href="/admin/mediaciones?date={{.Date}}&state={{.State}}&result={{.Result}}&page={{.PrevPage}}">Anterior</a>{{end}}{{if .More}}<a href="/admin/mediaciones?date={{.Date}}&state={{.State}}&result={{.Result}}&page={{.NextPage}}">Siguiente</a>{{end}}</div></section>`
const editTemplate = `<section class="card"><form action="/admin/editar" method="post"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="id" value="{{.M.ID}}"><div class="form-grid"><label>Sede<select name="sede">{{range .Sedes}}<option value="{{.Code}}" {{if eq $.M.Sede .Code}}selected{{end}}>{{.Name}}</option>{{end}}</select></label><label>Fecha<input type="text" inputmode="numeric" placeholder="dd/mm/aaaa" pattern="[0-9]{2}/[0-9]{2}/[0-9]{4}" maxlength="10" name="date" value="{{dateES .M.Date}}" required></label><label>Hora<input type="time" name="start" value="{{.M.Start}}" required></label><label>Mediador 1<select name="m1">{{range .Mediators}}<option value="{{.ID}}" {{if eqInt $.M.M1 .ID}}selected{{end}}>{{.Apellido}} {{.Nombre}} · {{.DNI}}</option>{{end}}</select></label><label>Mediador 2<select name="m2">{{range .Mediators}}<option value="{{.ID}}" {{if eqInt $.M.M2 .ID}}selected{{end}}>{{.Apellido}} {{.Nombre}} · {{.DNI}}</option>{{end}}</select></label><label>Carátula<input name="title" value="{{.M.Title}}" required maxlength="300"></label><label>Expediente<input name="case" value="{{.M.Case}}" required maxlength="120"></label></div><p class="muted">Cambiar sede, fecha, hora o mediadores vuelve a validar disponibilidad y conflictos. Cada cambio exige una nueva exportación.</p><button>Guardar cambios</button></form></section>`
const usersTemplate = `<form class="toolbar" action="/admin/usuarios" method="get" hx-get="/admin/usuarios" hx-target="#user-results" hx-select="#user-results" hx-swap="outerHTML"><input type="hidden" name="role" value="{{.Role}}"><label>Buscar nombre, DNI o email<input type="search" name="q" value="{{.Q}}"></label><button>Buscar</button></form>{{if eq .Role "ADMIN"}}<details class="card"><summary>Crear administrador</summary><form action="/admin/crear-admin" method="post"><input type="hidden" name="csrf" value="{{.CSRF}}"><label>Nombre<input name="name" required maxlength="100"></label><label>Usuario / email<input name="username" required maxlength="254"></label><label>Contraseña<input name="password" type="password" minlength="12" maxlength="72" required autocomplete="new-password"></label><button>Crear administrador</button></form></details>{{end}}<section id="user-results"><div class="table-wrap"><table><thead><tr><th>Persona</th><th>Contacto</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>{{range .Users}}<tr><td>{{if .Photo}}<img class="avatar" src="/uploads/{{.Photo}}" alt="Foto de {{.Nombre}}" loading="lazy">{{end}}{{.Apellido}} {{.Nombre}}<br>{{.DNI}} {{if eq .Role "ADMIN"}}{{.Username}}{{end}}</td><td>{{.Email}}<br>{{.Telefono}}</td><td>{{if .Active}}Activo{{else}}Inactivo{{end}}</td><td><form method="post" action="/admin/usuarios"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="id" value="{{.ID}}"><button name="action" value="toggle" class="secondary">{{if .Active}}Desactivar{{else}}Reactivar{{end}}</button></form><details><summary>Restablecer contraseña</summary><form method="post" action="/admin/usuarios"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="id" value="{{.ID}}"><label>Nueva contraseña<input type="password" name="password" minlength="12" maxlength="72" required autocomplete="new-password"></label><button name="action" value="reset">Restablecer</button></form></details></td></tr>{{else}}<tr><td colspan="4">No hay usuarios.</td></tr>{{end}}</tbody></table></div><div class="toolbar">{{if gt .Page 1}}<a href="/admin/usuarios?role={{.Role}}&q={{.Q}}&page={{.PrevPage}}">Anterior</a>{{end}}{{if .More}}<a href="/admin/usuarios?role={{.Role}}&q={{.Q}}&page={{.NextPage}}">Siguiente</a>{{end}}</div></section>`
const blocksTemplate = `<section class="card"><form action="/admin/bloqueos" method="post" data-confirm="¿Bloquear el día y cancelar todas sus mediaciones?"><input type="hidden" name="csrf" value="{{.CSRF}}"><div class="form-grid"><label>Sede<select name="sede">{{range .Sedes}}<option value="{{.Code}}">{{.Name}}</option>{{end}}</select></label><label>Fecha<input type="text" inputmode="numeric" placeholder="dd/mm/aaaa" pattern="[0-9]{2}/[0-9]{2}/[0-9]{4}" maxlength="10" name="date" required></label><label>Motivo opcional<input name="reason" maxlength="300"></label></div><p>Se cancelarán todas las mediaciones existentes para esa sede y fecha.</p><button class="danger">Bloquear día</button></form></section><div class="cards">{{range .Blocks}}<article class="card"><h2>{{dateES .Date}} · {{.Sede}}</h2><p>{{.Reason}}</p><form action="/admin/bloqueos" method="post"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="sede" value="{{.Sede}}"><input type="hidden" name="date" value="{{.Date}}"><button name="action" value="unblock" class="secondary">Desbloquear sin restaurar reservas</button></form></article>{{else}}<p>No hay días bloqueados.</p>{{end}}</div>`
const newsTemplate = `<section class="card"><h2>{{if .Edit.ID}}Editar noticia{{else}}Crear noticia{{end}}</h2><form action="/admin/noticias" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="id" value="{{.Edit.ID}}"><label>Título<input name="title" value="{{.Edit.Title}}" required maxlength="200"></label><label>Contenido<textarea name="content" rows="6" required maxlength="20000">{{.Edit.Content}}</textarea></label><label>Fecha de publicación<input type="text" inputmode="numeric" placeholder="dd/mm/aaaa" pattern="[0-9]{2}/[0-9]{2}/[0-9]{4}" maxlength="10" name="date" value="{{if .Edit.Date}}{{dateES .Edit.Date}}{{else}}{{dateES .Today}}{{end}}" required></label><label>Imagen opcional (JPEG/PNG, 5 MB)<input type="file" name="image" accept="image/jpeg,image/png"></label><label class="checkbox"><input type="checkbox" name="published" value="1" {{if .Edit.Published}}checked{{end}}>Publicar</label><button>Guardar noticia</button></form></section><div class="cards">{{range .News}}<article class="card"><h2>{{.Title}}</h2><p>{{dateES .Date}} · {{if .Published}}Publicada{{else}}Borrador{{end}}</p><a class="button secondary" href="/admin/noticias?id={{.ID}}">Editar</a><form action="/admin/noticias" method="post" data-confirm="¿Eliminar la noticia?"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="id" value="{{.ID}}"><button class="danger" name="action" value="delete">Eliminar</button></form></article>{{end}}</div>` + pagination
const whitelistTemplate = `<section class="card"><h2>Habilitar DNI manualmente</h2><form method="post" action="/admin/dnis"><input type="hidden" name="csrf" value="{{.CSRF}}"><div class="form-grid"><label>DNI<input name="dni" inputmode="numeric" maxlength="12" required></label><label>Nombre<input name="first" maxlength="100" required></label><label>Apellido<input name="last" maxlength="100" required></label><label>Email<input name="email" type="email" maxlength="254" required></label></div><button>Habilitar DNI</button></form></section><section class="card"><h2>Importar Excel o CSV</h2><p>XLSX o CSV. Si hay encabezados se reconocen apellido, nombre, DNI y email. Sin encabezados: A apellido, B nombre, C DNI, H email. Se omiten DNI existentes.</p><form action="/admin/importar" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="{{.CSRF}}"><label>Archivo XLSX o CSV<input type="file" name="xlsx" accept=".xlsx,.csv,.txt,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" required></label><button>Importar DNI</button></form></section><div class="table-wrap"><table><thead><tr><th>DNI</th><th>Nombre</th><th>Email</th></tr></thead><tbody>{{range .Users}}<tr><td>{{.DNI}}</td><td>{{.Apellido}} {{.Nombre}}</td><td>{{.Email}}</td></tr>{{else}}<tr><td colspan="3">No hay DNI pendientes.</td></tr>{{end}}</tbody></table></div>` + pagination
const exportsTemplate = `{{if .Pending}}<p class="warning">{{.Pending}} mediaciones pendientes de exportación. Fecha más antigua: {{dateES .Oldest}}. Se conservarán hasta que sean exportadas.</p>{{end}}<section class="card"><form action="/admin/exportar" method="post"><input type="hidden" name="csrf" value="{{.CSRF}}"><div class="form-grid"><label>Desde<input type="text" inputmode="numeric" placeholder="dd/mm/aaaa" pattern="[0-9]{2}/[0-9]{2}/[0-9]{4}" maxlength="10" name="from" required value="{{if .Oldest}}{{dateES .Oldest}}{{else}}{{dateES .Today}}{{end}}"></label><label>Hasta<input type="text" inputmode="numeric" placeholder="dd/mm/aaaa" pattern="[0-9]{2}/[0-9]{2}/[0-9]{4}" maxlength="10" name="to" required value="{{dateES .Today}}"></label></div><button>Exportar mediaciones</button></form><p class="muted">El archivo queda guardado y puede descargarse nuevamente. Solo se limpian días completamente exportados, pasados más de siete días.</p></section><div class="table-wrap"><table><thead><tr><th>Período</th><th>Fecha de exportación</th><th>Registros</th><th>Archivo</th></tr></thead><tbody>{{range .Exports}}<tr><td>{{dateES .From}} – {{dateES .To}}</td><td>{{timestampES .Created}}</td><td>{{.Count}}</td><td><a href="/admin/descargar/{{.File}}">Descargar XLSX</a></td></tr>{{else}}<tr><td colspan="4">No hay exportaciones.</td></tr>{{end}}</tbody></table></div>` + pagination
const auditTemplate = `<div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Actor</th><th>Acción</th><th>Entidad</th><th>Detalle</th></tr></thead><tbody>{{range .Entries}}<tr><td>{{timestampES .Date}}</td><td>{{.Actor}}</td><td>{{.Action}}</td><td>{{.Entity}} #{{.ID}}</td><td>{{detailES .Detail}}</td></tr>{{else}}<tr><td colspan="5">No hay eventos.</td></tr>{{end}}</tbody></table></div>` + pagination
const pagination = `<div class="toolbar">{{if gt .Page 1}}<a href="?page={{.PrevPage}}">Anterior</a>{{end}}<span>Página {{.Page}}</span>{{if .More}}<a href="?page={{.NextPage}}">Siguiente</a>{{end}}</div>`

const mediatorPickerTemplate = `<div id="mediator-picker"><label>Mediador 2<select id="mediator2" name="m2" required size="6"><option value="" selected>Seleccione un mediador</option>{{range .Mediators}}{{if not (eqInt .ID $.User.ID)}}<option value="{{.ID}}">{{.Apellido}} {{.Nombre}} · {{.DNI}}</option>{{end}}{{end}}</select></label>{{if not .Mediators}}<p role="status">No se encontraron mediadores activos.</p>{{end}}</div>`
const stateTemplate = `<section class="card narrow"><h2>{{.M.Title}}</h2><p>{{dateES .M.Date}} · {{.M.Start}} · {{.M.Sede}}</p><p>Expediente {{.M.Case}}</p><form method="post" action="/admin/estado"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="id" value="{{.M.ID}}"><label>Estado<select name="state">{{if eq .M.State "CANCELADA_POR_ADMIN"}}<option>CANCELADA_POR_ADMIN</option>{{else}}{{range $s:=editableStates}}<option {{if eq $.M.State $s}}selected{{end}}>{{$s}}</option>{{end}}{{end}}</select></label><label>Resultado<select name="result"><option value="">Sin resultado</option>{{range $s:=results}}<option {{if eq $.M.Result $s}}selected{{end}}>{{$s}}</option>{{end}}</select></label><button>Guardar estado</button></form></section>`
